import React, { useEffect, useState } from "react";
import Header from "../../components/Header/Header";
import Footer from "../../components/Footer/Footer";
import "./result-list-page.css";
import { useNavigate } from "react-router-dom";

type Test = {
  test_id: number;
  subjects: string;
  created_at: string;
};

type TestData = {
  incomplete_tests: Test[];
  tests_with_pending_results: Test[];
  tests_with_results: Test[];
};

const ResultListPage: React.FC = () => {
  const [testData, setTestData] = useState<TestData>({
    incomplete_tests: [],
    tests_with_pending_results: [],
    tests_with_results: [],
  });
  const [message, setMessage] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState("incomplete");
  const navigate = useNavigate();

  useEffect(() => {
    let isMounted = true;

    const fetchTestData = async () => {
      try {
        const email = localStorage.getItem("userEmail");
        if (!email) {
          if (isMounted) setMessage("Email not found. Please log in.");
          return;
        }

        const response = await fetch("http://localhost:5000/resultlist", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ email }),
        });

        if (isMounted) {
          if (response.ok) {
            const data: Partial<TestData> = await response.json();
            setTestData({
              incomplete_tests: data.incomplete_tests ?? [],
              tests_with_pending_results: data.tests_with_pending_results ?? [],
              tests_with_results: data.tests_with_results ?? [],
            });
          } else {
            const error = await response.json();
            setMessage(`Error: ${error.error || "Failed to fetch test data."}`);
          }
        }
      } catch (err: any) {
        if (isMounted) setMessage(`Error: ${err.message || "Something went wrong."}`);
      }
    };

    fetchTestData();
    const interval = setInterval(fetchTestData, 5000);

    return () => {
      isMounted = false;
      clearInterval(interval);
    };
  }, []);

  const renderTests = () => {
    let tests: Test[] = [];
    let actionLabel = "";
    let actionType = "";

    if (activeTab === "incomplete") {
      tests = testData.incomplete_tests;
      actionLabel = "Resume";
      actionType = "resume";
    } else if (activeTab === "pending") {
      tests = testData.tests_with_pending_results;
      actionLabel = "Check Result";
      actionType = "check_result";
    } else {
      tests = testData.tests_with_results;
      actionLabel = "View Result";
      actionType = "view_result";
    }

    return tests.length > 0 ? (
      <div className="test-table">
        <div className="test-header">
          <span>Test ID</span>
          <span>Subjects</span>
          <span>Created At</span>
          <span>Action</span>
        </div>
        {tests.map((test) => (
          <div key={test.test_id} className="test-item">
            <span>{test.test_id}</span>
            <span>{test.subjects}</span>
            <span>{test.created_at}</span>
            <button onClick={() => navigate("/completion-page")} className="action-button">
              {actionLabel}
            </button>
          </div>
        ))}
      </div>
    ) : (
      <p>No {activeTab} tests available.</p>
    );
  };

  return (
    <div className="App">
      <Header />
      <div className="result-container">
        <h2>Test Status</h2>
        {message && <p className="feedback-message">{message}</p>}
        {renderTests()}
      </div>
      <Footer />
    </div>
  );
};

export default ResultListPage;
